  Object.assign(state,{teRoute:'',teName:'',teColor:'#219c9c',teOriginal:''});
  const teColors=['#FF5722','#E91E63','#9C27B0','#673AB7','#3F51B5','#2196F3','#03A9F4','#00BCD4','#009688','#4CAF50','#8BC34A','#CDDC39','#FFC107','#FF9800','#795548','#607D8B','#F44336','#00E676','#FF4081','#536DFE'];
  function teInk(hex){const c=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]>.5?'#000':'#fff';}
  function teInit(){const key=state.page+':'+(state.leaf||'');if(state.teRoute!==key){state.teRoute=key;state.teName=state.page==='flow-tag-new'?'':state.leaf?.startsWith('编辑标签:')?state.leaf.slice(5):state.dTag||'日常';state.teOriginal=state.teName;state.teColor=state.page==='flow-tag-new'?'#009688':({日常:'#629b65',旅行:'#219c9c',工作日:'#a88b17'})[state.teName]||'#219c9c';}}
  function tePreview(){return `<span class="te-preview-pill" style="color:${state.teColor};background:${state.teColor}1f">${esc(state.teName.trim()||'标签名称')}</span>`;}
  function teBody(){teInit();return `${surface(`<div class="te-preview">${tePreview()}</div>`)}${surface(`<div class="te-name-field"><label class="te-input"><span>标签名称</span><input data-te-name aria-label="标签名称" placeholder="输入标签名称" value="${esc(state.teName)}"></label><small data-te-count>${[...new Intl.Segmenter('zh',{granularity:'grapheme'}).segment(state.teName)].length} / 20</small></div>`)}${surface(`<h3>标签颜色</h3><div class="te-palette">${teColors.map(hex=>btn('te-color:'+hex,`<span style="background:${hex};color:${teInk(hex)}">${state.teColor.toLowerCase()===hex.toLowerCase()?icon('check'):''}</span>`,'标签颜色 '+hex,'',`aria-pressed="${state.teColor.toLowerCase()===hex.toLowerCase()}"`)).join('')}</div>`)}`;}
  fDefs['tag-edit'].body=teBody;
  fDefine('tag-new','新增标签','分类标签与预算','tag/tag_edit_page.dart',teBody);tdPreviewGroup.appendChild(new Option('新建标签','flow-tag-new'));
  const teOldTools=fDefs['tag-tools'].body;fDefs['tag-tools'].body=()=>teOldTools().replace('f-go:tag-edit','f-go:tag-new');
  const tePreviousRender=fRender;fRender=function(key){if(!['tag-edit','tag-new'].includes(key))return tePreviousRender(key);return `<div class="bc-subhead"><div class="bc-heading-left">${btn('back',icon('chevron-left'),'返回')}<h2>${key==='tag-new'?'新增标签':'编辑标签'}</h2></div>${btn('te-save','保存','保存标签','te-save')}</div>`+teBody();};
  root.addEventListener('input',event=>{if(!event.target.matches('[data-te-name]'))return;const graphemes=[...new Intl.Segmenter('zh',{granularity:'grapheme'}).segment(event.target.value)];state.teName=graphemes.slice(0,20).map(p=>p.segment).join('');event.target.value=state.teName;phone.querySelector('.te-preview').innerHTML=tePreview();phone.querySelector('[data-te-count]').textContent=Math.min(20,graphemes.length)+' / 20';});
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const [action,arg]=el.dataset.action.split(':');if(!action.startsWith('te-'))return;event.preventDefault();event.stopImmediatePropagation();if(action==='te-color'){state.teColor=arg;render();}else if(action==='te-save'){if(!state.teName.trim()){notice('请输入标签名称','error');phone.querySelector('[data-te-name]').focus();return;}if(state.teName.trim()!==state.teOriginal&&tagColors[state.teName.trim()]){notice('标签名称已存在','error');return;}state.teName=state.teName.trim();if(state.teReturnTagLibrary&&typeof tlSaveDraft==='function'){tlSaveDraft(state.teName,state.teColor);return;}notice('标签已保存（演示草稿）','success');}},true);
